Gimle.Forseti.Fourier.Contract (Gimle.Asgard.Streams.NS.vorticityCircuit Gimle.Asgard.Streams.Basis.ogf 0)
  (fun input =>
    Eq (input 0 0)
      (Gimle.Asgard.Streams.Torus.Table.toTrig
        (List.cons { fst := { fst := 1, snd := 0 }, snd := 1 / 2 }
          (List.cons { fst := { fst := -1, snd := 0 }, snd := 1 / 2 }
            (List.cons { fst := { fst := 1, snd := 1 }, snd := 1 / 2 }
              (List.cons { fst := { fst := -1, snd := -1 }, snd := 1 / 2 }
                (List.cons { fst := { fst := 2, snd := 1 }, snd := 1 / 2 }
                  (List.cons { fst := { fst := -2, snd := -1 }, snd := 1 / 2 } List.nil))))))))
  fun output =>
  have ω := output 0;
  And
    (∀ (t : Real) (x : Prod Real Real),
      Real.instLE.le (abs t) (1 / 6480) → HasSum (ω.seriesTerm t x) (ω.analyticField t x))
    (ω.TruncationBound (1 / 6480) 3 (1 / 100))

